resumen_precios.dsl:
// Inspirada en la consulta 1 de TPC-H, sin su filtro de fecha (el DSL no tiene literales
// de fecha): resumen de cantidades y precios por estado de devolución y de línea.
PIPELINE resumen_precios {
    FROM PARQUET(file: "lineitem.parquet");
    DERIVE { precio_desc = l_extendedprice * (1 - l_discount); }
    DERIVE { cargo = precio_desc * (1 + l_tax); }
    AGGREGATE {
        GROUP_BY l_returnflag, l_linestatus;
        SUM(l_quantity) AS sum_qty;
        SUM(l_extendedprice) AS sum_base_price;
        SUM(precio_desc) AS sum_disc_price;
        SUM(cargo) AS sum_charge;
        AVG(l_quantity) AS avg_qty;
        AVG(l_extendedprice) AS avg_price;
        AVG(l_discount) AS avg_disc;
        COUNT() AS count_order;
    }
    SORT { BY l_returnflag, l_linestatus; }
    TO PARQUET(file: "salida/dsl/resumen_precios.parquet");
}

ingreso_descuento.dsl:
// Inspirada en la consulta 6 de TPC-H, sin su filtro de fecha: ingreso que dejarían los
// descuentos entre 0.05 y 0.07. Como en la consulta original, los límites se escriben
// 0.06 - 0.01 y 0.06 + 0.01. Cada condición va en su propio FILTER, como en la forma
// lineal; los pases "constantes" y "filtros" los simplifican y fusionan.
PIPELINE ingreso_descuento {
    FROM PARQUET(file: "lineitem.parquet");
    FILTER { WHERE l_discount >= 0.06 - 0.01; }
    FILTER { WHERE l_discount <= 0.06 + 0.01; }
    FILTER { WHERE l_quantity < 24; }
    DERIVE { ingreso = l_extendedprice * l_discount; }
    AGGREGATE { SUM(ingreso) AS ingreso_total; }
    TO PARQUET(file: "salida/dsl/ingreso_descuento.parquet");
}

ingreso_descuento.duckdb:
COPY (
    SELECT sum(l_extendedprice * l_discount) AS ingreso_total
    FROM read_parquet('$datos/lineitem.parquet')
    WHERE l_discount BETWEEN 0.06 - 0.01 AND 0.06 + 0.01
      AND l_quantity < 24
) TO '$salida/ingreso_descuento.parquet' (FORMAT parquet);

ingreso_por_pedido.dsl:
// Inspirada en la consulta 3 de TPC-H, sin sus filtros de fecha ni LIMIT: ingreso de cada
// pedido de los clientes del segmento BUILDING. Usa la forma de grafo porque tiene JOIN.
PIPELINE ingreso_por_pedido {
    SOURCE clientes = PARQUET(file: "customer.parquet");
    SOURCE pedidos = PARQUET(file: "orders.parquet");
    SOURCE lineas = PARQUET(file: "lineitem.parquet");

    STEP construccion = FILTER { WHERE c_mktsegment == "BUILDING"; }
    STEP con_pedidos = JOIN { TYPE INNER; ON left.c_custkey == right.o_custkey; }
    STEP con_lineas = JOIN { TYPE INNER; ON left.o_orderkey == right.l_orderkey; }
    STEP con_ingreso = DERIVE { ingreso = l_extendedprice * (1 - l_discount); }
    STEP por_pedido = AGGREGATE {
        GROUP_BY o_orderkey, o_orderdate, o_shippriority;
        SUM(ingreso) AS total;
    }
    STEP ordenado = SORT { BY total DESC, o_orderdate; }
    SINK salida = PARQUET(file: "salida/dsl/ingreso_por_pedido.parquet");

    FLOW {
        clientes -> construccion -> con_pedidos.left;
        pedidos -> con_pedidos.right;
        con_pedidos -> con_lineas.left;
        lineas -> con_lineas.right;
        con_lineas -> con_ingreso -> por_pedido -> ordenado -> salida;
    }
}

limpieza_pedidos.dsl:
// Limpieza de pedidos con datos faltantes y filas repetidas (orders_sucio, ver
// bench/datos.py): quita pedidos sin prioridad, completa precios nulos con 0, elimina
// duplicados exactos y resume por prioridad.
PIPELINE limpieza_pedidos {
    FROM PARQUET(file: "orders_sucio.parquet");
    DROP_NULLS { COLUMNS o_orderpriority; }
    FILL_NULL { o_totalprice = 0; }
    DISTINCT {
        COLUMNS o_orderkey, o_custkey, o_orderstatus, o_totalprice,
                o_orderdate, o_orderpriority, o_clerk, o_shippriority;
    }
    AGGREGATE {
        GROUP_BY o_orderpriority;
        COUNT() AS pedidos;
        SUM(o_totalprice) AS total;
        AVG(o_totalprice) AS promedio;
    }
    SORT { BY o_orderpriority; }
    TO PARQUET(file: "salida/dsl/limpieza_pedidos.parquet");
}

devoluciones.dsl:
// Dos resultados de una misma cadena: todas las líneas devueltas y un resumen por modo de
// envío. Mide el costo de tener dos TO: hoy cada salida vuelve a leer y filtrar lineitem.
PIPELINE devoluciones {
    FROM PARQUET(file: "lineitem.parquet");
    FILTER { WHERE l_returnflag == "R"; }
    TO PARQUET(file: "salida/dsl/devoluciones.parquet");
    AGGREGATE {
        GROUP_BY l_shipmode;
        COUNT() AS lineas;
        SUM(l_extendedprice) AS total;
    }
    SORT { BY l_shipmode; }
    TO PARQUET(file: "salida/dsl/devoluciones_por_envio.parquet");
}

devoluciones.duckdb:
CREATE TEMP TABLE devueltas AS
    SELECT * FROM read_parquet('$datos/lineitem.parquet') WHERE l_returnflag = 'R';

COPY devueltas TO '$salida/devoluciones.parquet' (FORMAT parquet);

COPY (
    SELECT l_shipmode, count(*) AS lineas, sum(l_extendedprice) AS total
    FROM devueltas
    GROUP BY l_shipmode
    ORDER BY l_shipmode
) TO '$salida/devoluciones_por_envio.parquet' (FORMAT parquet);
